  'No data yet': 'Sin datos aún',
  'Ranks': 'Rangos',
  'How ranks work, what you need, how many there are': 'Cómo se consiguen, qué hace falta y cuántos hay',
  'The 9 tiers': 'Los 9 rangos',
  'From {0} to {1}, each with three divisions — I, II and III. You move up a division, then the next one, before moving into the next tier. {2} is the top, for the very strongest lifts, and has no divisions.': 'De {0} a {1}, cada uno con tres divisiones — I, II y III. Subes de división, luego a la siguiente, antes de pasar al próximo rango. {2} es el techo, para las marcas más fuertes, y no tiene divisiones.',
  'What you need': 'Qué hace falta',
  'Log your bodyweight, then log sets for any of {0} curated lifts (bench press, squat, deadlift, overhead press, pull-up, chin-up, dip, row, romanian deadlift, curl, calf raise) — each ranks on its own as soon as it has one. The overall rank needs at least {1} of them.': 'Registra tu peso corporal, y luego series de cualquiera de estos {0} ejercicios (press de banca, sentadilla, peso muerto, press militar, dominada, dominada supina, fondos, remo, peso muerto rumano, curl de bíceps, elevación de gemelo) — cada uno saca su rango en cuanto tiene una serie. El rango global necesita al menos {1} de ellos.',
  'How strength rank works': 'Cómo funciona el rango de fuerza',
  'Your rank in each lift comes from your best set, weighed against your bodyweight — the same idea powerlifting uses to compare weight classes, so a lighter and a heavier lifter compete fairly. No need to test a true max: your normal working sets are enough.': 'Tu rango en cada ejercicio sale de tu mejor serie, ajustada a tu peso corporal — la misma idea que usa el powerlifting para comparar categorías de peso, así una persona más ligera y otra más pesada compiten en igualdad. No hace falta testear un máximo real: tus series normales de entreno bastan.',
  'Exercise ranks that train a muscle combine into that muscle\'s rank, weighing exercises with more sets more heavily. Muscles combine into a group rank (chest, back, shoulders, arms, legs, core), and every group combines into one overall rank — a complete physique outweighs a single strong lift.': 'Los rangos de los ejercicios que trabajan un músculo se combinan en el rango de ese músculo, dando más peso a los ejercicios con más series. Los músculos se combinan en un rango de grupo (pecho, espalda, hombros, brazos, piernas, core), y todos los grupos se combinan en un rango global — un físico completo pesa más que un solo ejercicio fuerte.',
  'Ranks are checked against published strength standards, not against this gym\'s own members — there aren\'t enough accounts here for a real comparison yet. Treat the tiers as a rough guide and not a certified measurement.': 'Los rangos se comparan contra estándares de fuerza publicados, no contra los socios de este gimnasio — todavía no hay cuentas suficientes para una comparación real. Toma los tramos como una guía orientativa, no como una medición certificada.',
  'Search…': 'Buscar…',
