  "Open Chrome's menu (⋮).": 'Abre el menú de Chrome (⋮).',
  'Choose Install app or Add to Home screen.': 'Elige «Instalar aplicación» o «Añadir a pantalla de inicio».',
  'Confirm the installation.': 'Confirma la instalación.',
  "Open Edge's menu (⋯).": 'Abre el menú de Edge (⋯).',
  'Choose Add to phone or Install app, if available.': 'Elige «Añadir al teléfono» o «Instalar aplicación», si aparece.',
  'Open the browser menu (⋮).': 'Abre el menú del navegador (⋮).',
  'Open the Install icon in the address bar or Chrome menu.': 'Abre el icono de instalación de la barra de direcciones o el menú de Chrome.',
  'Choose Install 2J Fitness or Install page as app, if shown.': 'Elige «Instalar 2J Fitness» o «Instalar página como aplicación», si aparece.',
  'Open Edge menu → Apps.': 'Abre el menú de Edge → Aplicaciones.',
  'Choose Install this site as an app, if available.': 'Elige «Instalar este sitio como aplicación», si aparece.',
  'Open the browser menu or sharing options.': 'Abre el menú del navegador o las opciones para compartir.',
