  '{0} x {1} {2}': '{0} x {1} {2}',
  'Plate calculator quick access': 'Acceso rápido a la calculadora de discos',
  'Show the quick-access icon to calculate barbell plates on each set.': 'Muestra el acceso rápido para calcular los discos de la barra en cada serie.',
  'Training zones': 'Zonas de entrenamiento',
  'Calculate and show relative effort, RPE and %1RM while training.': 'Calcula y muestra el esfuerzo relativo, RPE y %1RM durante los ejercicios.',
  'What are Training zones?': '¿Qué son las Zonas de entrenamiento?',
  'Every logged set is placed into one of 5 standard strength-training zones, so you can see at a glance what kind of effort a session is actually made of.':
    'Cada serie registrada se clasifica en una de las 5 zonas estándar de entrenamiento de fuerza, para que veas de un vistazo de qué tipo de esfuerzo está hecha realmente una sesión.',
  'Whenever this exercise already has an estimated 1RM (from your best set on record, or a test you logged), the zone comes from the set’s weight as a % of that 1RM — the most direct signal. Without an estimate yet — a brand-new exercise, or one you’ve only trained for very high reps — it falls back to the RIR/RPE you rated the set with instead.':
    'Cuando este ejercicio ya tiene un 1RM estimado (de tu mejor serie registrada, o de una prueba que hiciste), la zona sale del peso de la serie como % de ese 1RM — la señal más directa. Si aún no hay una estimación — un ejercicio nuevo, o uno que solo has entrenado a muchas repeticiones — usa en su lugar el RIR/RPE que registraste en la serie.',
  'The coloured chip on each set (in the logger), the target-zone picker when planning a routine’s exercise, and the weekly/monthly volume-by-zone chart in Progress all read from the same calculation, and all turn off together with the switch above.':
    'La etiqueta de color en cada serie (en el registro), el selector de zona objetivo al planificar un ejercicio de rutina, y el gráfico de volumen por zona semanal/mensual en Progreso usan todos el mismo cálculo, y se desactivan todos juntos con el interruptor de arriba.',
  'What does this affect?': '¿Qué afecta esto?',
  'Progressive overload coach': 'Asistente de sobrecarga progresiva',
  'Show references from your last workout and overload targets on each set.': 'Muestra referencias de tu último entreno y metas de sobrecarga en cada serie.',
  'What is the overload coach?': '¿Qué es el asistente de sobrecarga?',
  'A standing suggestion for what to aim for next on any exercise you’ve trained before, plus a clear signal the moment you actually beat it.':
    'Una sugerencia permanente de a qué aspirar en cualquier ejercicio que ya hayas entrenado antes, más una señal clara en el momento en que realmente lo superas.',
  'The target chip': 'La etiqueta de objetivo',
  'If your heaviest set last time hit the top of this exercise’s rep target, the suggestion is more weight, same reps. If it fell short, the suggestion holds the weight and asks for one more rep instead. Either way it’s a suggestion, not something the app changes for you — tap a set’s own “last time” placeholder to fill it in.':
    'Si tu serie más pesada la última vez llegó al tope del rango de repeticiones de este ejercicio, la sugerencia es más peso, mismas repeticiones. Si se quedó corta, la sugerencia mantiene el peso y pide una repetición más. En ambos casos es solo una sugerencia, no algo que la app cambie por ti — toca el texto de «la última vez» de una serie para rellenarla.',
  'Beating it': 'Superarla',
  'A set that matches or beats the equivalent one from last time turns its checkmark green. One that also beats this exercise’s best-ever estimated 1RM turns it gold instead, with “New PR this session!” underneath the sets.':
    'Una serie que iguala o supera a la equivalente de la última vez pone su check en verde. Una que además supera el mejor 1RM estimado de este ejercicio lo pone en dorado, con «¡Nuevo récord esta sesión!» debajo de las series.',
  'Target: {0} {1} × {2}': 'Objetivo: {0} {1} × {2}',
  'New PR this session!': '¡Nuevo récord esta sesión!',
  'Overload achieved': 'Sobrecarga lograda',
  'Weekly volume zones': 'Zonas de volumen semanal',
  'Calculate MV, MEV, MAV and MRV per muscle group and show your weekly progress live.': 'Calcula MV, MEV, MAV y MRV por grupo muscular y muestra tu progreso semanal en vivo.',
  'What are weekly volume zones?': '¿Qué son las zonas de volumen semanal?',
  'Training level': 'Nivel de entrenamiento',
  'Muscle growth tracks the number of effective sets a muscle gets in a week, not just how heavy any one of them was — too few and nothing adapts, too many and you can’t recover before the next session. This shows, per muscle group, which of five zones this week’s count actually lands in.':
    'El crecimiento muscular depende del número de series efectivas que recibe un músculo en una semana, no solo de lo pesada que fue una de ellas — muy pocas y no hay adaptación, demasiadas y no te recuperas antes de la próxima sesión. Esto muestra, por grupo muscular, en cuál de las cinco zonas cae el número de esta semana.',
  'Meaning': 'Significado',
  'Your training level (Beginner / Intermediate / Advanced) picks which set of weekly targets applies — a more experienced lifter tolerates, and needs, more volume to keep growing. Turning this on hides the per-set %1RM/RPE zone chip in the logger — the two are both called “zones” but answer different questions, and showing both at once was more confusing than either alone.':
    'Tu nivel de entrenamiento (Principiante / Intermedio / Avanzado) determina qué tabla de objetivos semanales se aplica — cuanto más experimentado eres, más volumen toleras y necesitas para seguir creciendo. Al activarlo se oculta la etiqueta de zona %1RM/RPE de cada serie en el registro — ambas se llaman «zonas» pero responden preguntas distintas, y mostrar las dos a la vez resultaba más confuso que cualquiera de las dos por separado.',
