  '{0} new badges': '{0} insignias nuevas',
  'Controls how a secondary — supporting — muscle counts toward the numbers this app derives from your training, wherever they’re shown.':
    'Controla cómo cuenta un músculo secundario — de apoyo — en los números que esta app calcula a partir de tu entrenamiento, dondequiera que se muestren.',
  'What counts as secondary?': '¿Qué cuenta como secundario?',
  'A bench press mainly trains chest — its primary muscle — but triceps and shoulders help too. Those helpers are the secondary muscles. With counting on, a secondary muscle credits a fraction of a full set (the factor below); with it off, only the primary muscle gets any credit at all.':
    'Un press de banca entrena principalmente el pecho — su músculo principal — pero tríceps y hombros también ayudan. Esos ayudantes son los músculos secundarios. Con el conteo activado, un músculo secundario acredita una fracción de una serie completa (el factor de abajo); con él desactivado, solo el músculo principal recibe algún crédito.',
  'Where this shows up': 'Dónde se ve esto',
  'The muscle map (Home and Progress), muscle recovery’s per-muscle % and the Progress screen’s muscle balance card all read the same two settings — turning secondaries off, or changing their factor, updates every one of them at once, never just one screen.':
    'El mapa muscular (Inicio y Progreso), el % por músculo de la recuperación muscular y la tarjeta de equilibrio muscular de Progreso usan los mismos dos ajustes — desactivar los secundarios, o cambiar su factor, actualiza los tres a la vez, nunca solo una pantalla.',
