  'Held every set for the full time — target up by {0}s.': 'Aguantaste todas las series el tiempo completo: objetivo +{0} s.',
  'Short {0} sessions in a row — back off to {1}s and build up again.': '{0} sesiones seguidas por debajo: baja a {1} s y vuelve a subir.',
  'Last time came up short — same target again.': 'La última vez te quedaste corto: el mismo objetivo otra vez.',
  'Top of the rep range in every set — {0} {1} more, back to {2} reps.': 'Tope del rango en todas las series: {0} {1} más, vuelta a {2} repeticiones.',
  'Stalled {0} sessions — deload to {1} {2}.': '{0} sesiones estancado: descarga a {1} {2}.',
