  'What do you want to prioritize? (up to 2)': '¿Qué quieres priorizar? (hasta 2)',
  'Anything else? (up to 3)': '¿Algo más? (hasta 3)',
  'Training priorities': 'Prioridades de entrenamiento',
  'Optional. The quick plan and the AI Coach give these a little more work than the rest.': 'Opcional. Tanto el plan rápido como el AI Coach le dan algo más de trabajo a esto que al resto.',
  // Coach consent screen (Coach.jsx CATEGORY_TEXT) — also t(variable), also leaking English
  'Routines, exercises, sets and reps, your weekly schedule, progression settings and active Guided Program progress.': 'Rutinas, ejercicios, series y repeticiones, horario semanal, progresión y avance del Programa Guiado activo.',
  'Your logged training': 'Tu entrenamiento registrado',
  'Sets you logged in the review window — weights, reps, times, effort ratings and how long sessions took.': 'Las series que registraste en la ventana revisada — pesos, repeticiones, tiempos, valoración de esfuerzo y duración de las sesiones.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Los pesajes de esa misma ventana, y tu peso objetivo si has puesto uno.',
  'What you tell the Coach': 'Lo que le cuentas al Coach',
  'Your intake answers, including any limitations or injuries you describe, plus your age, sex and height from your account basics.': 'Tus respuestas del cuestionario, incluidas las limitaciones o lesiones que describas, además de tu edad, sexo y altura de tus datos básicos.',
  'A few preferences': 'Algunas preferencias',
  'Your unit, your language, which effort scale you log, and — when you’ve turned them on — your training level and weekly volume/intensity zone targets.': 'Tu unidad, tu idioma, la escala de esfuerzo que registras y — cuando los tengas activados — tu nivel de entrenamiento y tus objetivos de zonas de volumen/intensidad semanales.',

  // Registration basics (name, date of birth, sex, height, starting weight) + Settings edit rows
  'Basic info': 'Datos básicos',
  'Date of birth': 'Fecha de nacimiento',
  'Height': 'Altura',
  'Height (cm)': 'Altura (cm)',
  'Optional, and you can change it later in Settings — helps the AI Coach tailor your plan.': 'Opcional, y puedes cambiarlo después en Ajustes — ayuda al Coach de IA a ajustar tu plan.',
  'Sex': 'Sexo',
  'Sex uses the Body diagram choice below. Starting weight is your first body-weight log — add or edit it from Home.': 'El sexo usa la opción de Diagrama corporal de abajo. El peso inicial es tu primer registro de peso — añádelo o edítalo desde Inicio.',
  'Sex uses the Body diagram choice in Settings. Starting weight is your first body-weight log — add or edit it from Home.': 'El sexo usa la opción de Diagrama corporal en Ajustes. El peso inicial es tu primer registro de peso — añádelo o edítalo desde Inicio.',
  'Starting weight ({0})': 'Peso inicial ({0})',

