  // AI Coach demo content + a few strings missed by earlier passes
  'A pull for every press, so the shoulders stay balanced.': 'Un ejercicio de tirón por cada empuje, para mantener los hombros equilibrados.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Una rotación de dos días a lo largo de tres sesiones semanales, pensada según el equipo que indicaste. Multiarticulares primero, un tirón por cada empuje, y suficiente solapamiento entre los días para que nada pase dos semanas sin trabajarse.',
  'Based on the training already in this demo profile.': 'Basado en el entrenamiento que ya tiene este perfil de demostración.',
  'Body weight has been flat for four weeks while the goal is to gain. That is a kitchen problem rather than a training one — the plan is not what is holding it back.': 'El peso corporal lleva cuatro semanas sin moverse mientras el objetivo es ganar. Eso es un tema de alimentación, no de entrenamiento — el plan no es lo que lo está frenando.',
  'Coach plan': 'Plan del Coach',
  'Direct arm work, since you asked for it.': 'Trabajo directo de brazo, ya que lo pediste.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Cada serie principal de este ejercicio ha llegado a RPE 9,5 o más durante tres sesiones y el peso no se ha movido. Cambiar el movimiento durante cuatro semanas suele romper ese estancamiento más rápido que insistir con el mismo.',
  'Exercise': 'Ejercicio',
  'Full body A': 'Cuerpo completo A',
  'Full body B': 'Cuerpo completo B',
  'Horizontal pressing, the other half of the session.': 'Empuje horizontal, la otra mitad de la sesión.',
  'Live demo — everything stays in this browser.': 'Demo en vivo — todo se queda en este navegador.',
  'No exercises yet.': 'Aún no hay ejercicios.',
  'No training history yet — starting conservatively.': 'Todavía no hay historial de entrenamiento — empezando de forma conservadora.',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Revisado como pediste. Todo lo que no cuestionaste sigue exactamente igual.',
  'Same pattern, higher reps than day A.': 'Mismo patrón, más repeticiones que el día A.',
  'Self-host it in a minute →': 'Aloja tu propia instancia en un minuto →',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Las sesiones se están alargando unos quince minutos de más. Este es el accesorio que menos pierde con una serie menos.',
  'Start the demo': 'Empezar la demo',
  'The Coach is already thinking about your training.': 'El Coach ya está pensando en tu entrenamiento.',
  'The main lower-body driver — where most of the strength comes from.': 'El motor principal de tren inferior — de donde sale la mayor parte de la fuerza.',
  'The same patterns, different variations — enough overlap to progress, enough difference to stay fresh.': 'Los mismos patrones, variaciones distintas — suficiente solapamiento para progresar, suficiente diferencia para no estancarse.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Los dos grandes patrones de tren inferior y empuje primero, mientras estás fresco.',
  'This demo runs entirely in your browser on example data — nothing is sent anywhere. Passkey sign-in and sync across your devices come with the 2J Fitness Center server, which you get by self-hosting it.': 'Esta demo se ejecuta enteramente en tu navegador con datos de ejemplo — no se envía nada a ningún sitio. El inicio de sesión con passkey y la sincronización entre dispositivos vienen con el servidor de 2J Fitness Center, que obtienes alojándolo tú mismo.',
  'Three things worth changing, and one worth knowing about. Everything else is working — the squat and the pulls are both progressing on schedule.': 'Tres cosas que merece la pena cambiar, y una que conviene saber. Todo lo demás funciona — la sentadilla y los tirones progresan según lo previsto.',
  'Vertical pressing.': 'Empuje vertical.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Has movido esta sesión al sábado tres semanas seguidas. Mejor que lo diga el plan a que lo sigas cambiando tú.',

