  // ---- Muscle recovery (Home card + /recovery detail screen) ----
  'Muscle recovery': 'Recuperación muscular',
  'See which muscles are ready to train': 'Mira qué músculos están listos para entrenar',
  'Push muscles': 'Músculos de empuje',
  'Pull muscles': 'Músculos de tirón',
  'Leg muscles': 'Músculos de piernas',
  'Core': 'Core',
  'How recovery works': 'Cómo funciona la recuperación',
  'About': 'Acerca de',
  'Muscle recovery estimates how ready each muscle group is to train again, based on your recently logged sets.': 'La recuperación muscular estima qué tan listo está cada grupo muscular para entrenar de nuevo, según tus series registradas recientemente.',
  'How it’s calculated': 'Cómo se calcula',
  'We give more weight to recent sessions. Each set counts for the muscle it targets — full for the main muscle, half for supporting ones — more reps count for more, and a set taken closer to failure (RIR/RPE) counts for more too. Time-based work (holds, cardio) isn’t included.': 'Damos más peso a las sesiones recientes. Cada serie cuenta para el músculo al que va dirigida — completa para el músculo principal, la mitad para los que ayudan — las series con más repeticiones cuentan más, y una serie hecha más cerca del fallo (RIR/RPE) también cuenta más. El trabajo por tiempo (isométricos, cardio) no se incluye.',
  'Recovery windows': 'Ventanas de recuperación',
  'Bigger muscle groups (back, quads, hamstrings, glutes) take longer to read as fully recovered — up to 72h — than smaller ones (chest, shoulders, arms, calves, core), which clear in about 48h.': 'Los grupos musculares más grandes (espalda, cuádriceps, isquios, glúteos) tardan más en marcarse como totalmente recuperados — hasta 72h — que los más pequeños (pecho, hombros, brazos, gemelos, core), que se recuperan en unas 48h.',
  'Keep in mind': 'Ten en cuenta',
  'This is only an estimate. It doesn’t account for sleep, stress or nutrition. Custom exercises need a muscle tag to be included.': 'Esto es solo una estimación. No tiene en cuenta el sueño, el estrés ni la nutrición. Los ejercicios personalizados necesitan una etiqueta de músculo para incluirse.',
  'Overall recovery': 'Recuperación general',
  'Average recovery across every muscle group, based on your recent training.': 'Recuperación media de todos los grupos musculares, según tu entrenamiento reciente.',
  'Fatigued': 'Fatigado',
  'Recovering': 'Recuperando',
  'Ready': 'Listo',
  'Ready in ~{0}h': 'Listo en ~{0}h',

