  'Energy': 'Energía',
  'Estimate (220 − age)': 'Estimada (220 − edad)',
  'Experimental · works on this device': 'Experimental · funciona en este dispositivo',
  'Experimental. Connect a chest strap or armband from the workout screen; 2J shows your live heart rate and saves the session average, maximum and zones — never the raw stream or the device.': 'Experimental. Conecta una banda de pecho o de brazo desde la pantalla de entreno; 2J muestra tu pulso en directo y guarda la media, el máximo y las zonas de la sesión — nunca el flujo en bruto ni el dispositivo.',
  'Export from the Health app (profile → Export All Health Data) and import the file here. Workouts recorded by Apple Watch — or by apps that write to Health, like Zepp — bring their calories and heart rate; they are linked to a 2J workout only when the times clearly match. The file comes from an iPhone; you can upload it from any device, but this is a manual file import, not an Android integration.': 'Exporta desde la app Salud (perfil → Exportar todos los datos de salud) e importa el archivo aquí. Los entrenos registrados por el Apple Watch — o por apps que escriben en Salud, como Zepp — traen sus calorías y pulso; solo se vinculan a un entreno de 2J cuando las horas coinciden claramente. El archivo sale de un iPhone; puedes subirlo desde cualquier dispositivo, pero es una importación manual de archivo, no una integración con Android.',
