  'The activity stays in {0}; only its link to this workout is removed.': 'La actividad sigue en {0}; solo se quita su vínculo con este entreno.',
  'The check-in is a few taps before training, never required. Max heart rate is only used to split heart-rate data into zones; without it 2J uses the 220 − age estimate and says so.': 'El check-in son unos toques antes de entrenar, nunca obligatorio. La FC máxima solo se usa para repartir el pulso en zonas; sin ella 2J usa la estimación 220 − edad y lo indica.',
  'These activities overlap more than one workout, or only partly. Choose, or skip — nothing is linked on a guess.': 'Estas actividades se solapan con más de un entreno, o solo en parte. Elige u omite — nada se vincula a ojo.',
