  'Rest alert behavior: Android schedules a private local notification when permission is allowed. If notifications are denied, the timer still works; allow 2J notifications in Android settings and turn this alert off and on again. In a browser, background alerts require an internet connection.': 'En Android se programa un aviso local y privado si se permite. Si deniegas las notificaciones, el temporizador seguirá funcionando; permite las notificaciones de 2J en Ajustes de Android y apaga y vuelve a activar este aviso. En el navegador, los avisos en segundo plano requieren conexión a Internet.',
