  'Squat and press patterns for the quads with free weights. Dynamic warm-up, the main block with prescribed sets and rest, and a cool-down.': 'Patrones de sentadilla y prensa para los cuádriceps con peso libre. Calentamiento dinámico, el bloque principal con series y descansos prescritos y vuelta a la calma.',
  'Glutes · Advanced B': 'Glúteos · Avanzado B',
  'Bridges, hinges and abduction for the glutes with heavier loads and longer rests. Dynamic warm-up, the main block with prescribed sets and rest, and a cool-down.': 'Puentes, bisagras y abducciones para los glúteos con cargas más pesadas y descansos más largos. Calentamiento dinámico, el bloque principal con series y descansos prescritos y vuelta a la calma.',
  'Hamstrings · Advanced A': 'Isquiotibiales · Avanzado A',
  'Hinges and curls for the hamstrings with a focus on time under tension. Dynamic warm-up, the main block with prescribed sets and rest, and a cool-down.': 'Bisagras y curls para los isquios con foco en el tiempo bajo tensión. Calentamiento dinámico, el bloque principal con series y descansos prescritos y vuelta a la calma.',
  'Lower body · Advanced': 'Tren inferior · Avanzado',
  'Squats, hinges and calves for the legs with heavier loads and longer rests. Dynamic warm-up, the main block with prescribed sets and rest, and a cool-down.': 'Sentadillas, bisagras y gemelos para las piernas con cargas más pesadas y descansos más largos. Calentamiento dinámico, el bloque principal con series y descansos prescritos y vuelta a la calma.',
  'Full body · Advanced': 'Cuerpo completo · Avanzado',
  'A balanced session for the whole body with heavier loads and longer rests. Dynamic warm-up, the main block with prescribed sets and rest, and a cool-down.': 'Una sesión equilibrada para todo el cuerpo con cargas más pesadas y descansos más largos. Calentamiento dinámico, el bloque principal con series y descansos prescritos y vuelta a la calma.',
  'Warm-ups': 'Calentamientos',
  'Get ready in five minutes: upper, lower, glutes, running or the whole body.': 'Prepárate en cinco minutos: tren superior, inferior, glúteos, correr o todo el cuerpo.',
  'Cool-down and stretching': 'Vuelta a la calma y estiramientos',
  'Wind down after training or stretch on a rest day, from five to twenty-five minutes.': 'Baja revoluciones tras entrenar o estira en un día libre, de cinco a veinticinco minutos.',
  'Easy flows for the day after a hard session or a week off.': 'Flujos suaves para el día después de una sesión dura o tras una semana libre.',
  'Finishers': 'Finales de sesión',
  'Short machine bursts to finish a strength day.': 'Ráfagas cortas en máquina para cerrar un día de fuerza.',
  'Only your body: sessions for home, a hotel or a park.': 'Solo tu cuerpo: sesiones para casa, un hotel o un parque.',
  'No jumps and no running: kind to knees and joints.': 'Sin saltos ni carrera: amable con rodillas y articulaciones.',
  'Thirty minutes or more': 'Treinta minutos o más',
  'When you have time: full strength days and long flows.': 'Cuando tienes tiempo: días completos de fuerza y flujos largos.',
  // Programs — content expansion
  '2J · Flexibility': '2J · Flexibilidad',
  'Four weeks of slow stretching and mobility, from the hips and back to the neck and shoulders. Floor and standing, no equipment.': 'Cuatro semanas de estiramientos lentos y movilidad, de caderas y espalda a cuello y hombros. En el suelo y de pie, sin material.',
  '2J · Active recovery': '2J · Recuperación activa',
  'Two easy weeks to recover between hard blocks: gentle flows, long holds and hip work.': 'Dos semanas suaves para recuperar entre bloques duros: flujos tranquilos, estiramientos largos y trabajo de caderas.',
  '2 weeks': '2 semanas',
  '2J · Machine HIIT': '2J · HIIT en máquinas',
  'Four weeks of interval work on the treadmill, stepmill, SkiErg, bike and elliptical, two hard sessions a week.': 'Cuatro semanas de intervalos en cinta, escaladora, SkiErg, bici y elíptica, con dos sesiones duras por semana.',
  '2J · Low-impact cardio': '2J · Cardio de bajo impacto',
  'Four weeks of bike, elliptical, stepmill and SkiErg intervals with a stretch each week. No running, no jumps.': 'Cuatro semanas de intervalos en bici, elíptica, escaladora y SkiErg con un estiramiento cada semana. Sin correr y sin saltos.',
  '2J · Tabata block': '2J · Bloque Tabata',
  'Four weeks of 20/10 sessions on the machines and with your body, three short sessions a week.': 'Cuatro semanas de sesiones 20/10 en máquinas y con tu cuerpo, tres sesiones cortas por semana.',
  '2J · Strength and cardio': '2J · Fuerza y cardio',
  'Three weeks that pair a strength block with a machine finisher in every session.': 'Tres semanas que combinan un bloque de fuerza con un final en máquina en cada sesión.',
  '2J · No-equipment HIIT': '2J · HIIT sin material',
  'Three weeks of bodyweight intervals and circuits for home or a hotel room, with a stretch to finish each week.': 'Tres semanas de intervalos y circuitos con tu cuerpo para casa o una habitación de hotel, con un estiramiento para cerrar cada semana.',
  '2J · Four-day split': '2J · Rutina dividida de cuatro días',
  'Chest, back, legs and shoulders on four days a week, with new variations every week.': 'Pecho, espalda, pierna y hombros en cuatro días por semana, con variaciones nuevas cada semana.',
  '2J · Beginner split': '2J · Rutina dividida para empezar',
  'Three days a week, one area each day, with a short warm-up. Machines and cables, generous rest.': 'Tres días por semana, una zona cada día, con un calentamiento corto. Máquinas y poleas, descansos generosos.',
