  'Every routine is made of official blocks and validated by the 2J protocol before it can go live. Errors tell you what to fix.': 'Cada rutina se compone de bloques oficiales y se valida con el protocolo 2J antes de publicarse. Los errores te dicen qué corregir.',
  'Draft, preview, publish': 'Borrador, vista previa, publicar',
  'New and duplicated content starts as a draft only admins see. Preview it exactly as a member would, then publish it. Hide it any time: people who already started keep their own copy.': 'El contenido nuevo o duplicado empieza como borrador que solo ve administración. Míralo tal como lo vería un socio y luego publícalo. Puedes ocultarlo cuando quieras: quien ya lo empezó conserva su propia copia.',
  'Programs and collections': 'Programas y colecciones',
  'Programs chain routines week by week. Collections group routines and programs on the library home. Order and featured decide what members see first.': 'Los programas encadenan rutinas semana a semana. Las colecciones agrupan rutinas y programas en el inicio de la biblioteca. El orden y los destacados deciden qué ven primero los socios.',
  'Move down': 'Bajar',
  'Home and hotel': 'Casa y hotel',
  '2J stops reading it on this device. Workouts already linked keep their data. To revoke access completely, use your phone’s Health settings.': '2J deja de leerlo en este dispositivo. Los entrenos ya vinculados conservan sus datos. Para revocar el acceso por completo, usa los ajustes de Salud de tu teléfono.',
  'Connect first': 'Conéctalo primero',
  'Connected. Nothing is read until you sync.': 'Conectado. No se lee nada hasta que sincronices.',
