  'automatic': 'automático',
  'Health Connect': 'Health Connect',
  '2J stops writing to Health. Workouts already sent stay there; 2J never edits or deletes them.': '2J deja de escribir en Salud. Los entrenos ya enviados se quedan allí; 2J nunca los edita ni los borra.',
  '2J will send the workouts you finish to Health.': '2J enviará a Salud los entrenos que termines.',
  'Only workouts you finish in 2J. On Android, if Health still has no calories for one after about 15 min, 2J adds a labelled estimate.': 'Solo los entrenos que termines en 2J. En Android, si Health sigue sin calorías de uno tras unos 15 min, 2J añade una estimación etiquetada.',
