  'Consider rest and the priorities of the program before changing the order.': 'Considera el descanso y las prioridades del programa antes de cambiar el orden.',
  '{0} planned exercises are missing from most of the recent sessions.': '{0} ejercicios planificados faltan en la mayoría de las sesiones recientes.',
  'The period reviewed may not be representative.': 'El periodo revisado puede no ser representativo.',
  'Confirm first that the period reviewed is representative.': 'Confirma primero que el periodo revisado sea representativo.',
  'A reference range needs a whole week of routines.': 'Un rango de referencia necesita una semana completa de rutinas.',
  'Reference ranges only apply to hypertrophy programs.': 'Los rangos de referencia solo se aplican a programas de hipertrofia.',
  'Set the level to compare with a reference range.': 'Indica el nivel para comparar con un rango de referencia.',
  '{0} sets · {1} d': '{0} series · {1} d',
  '{0} ex. · {1} d': '{0} ej. · {1} d',
