  'Ready-made workouts': 'Entrenamientos ya hechos',
  'Today’s plan': 'El plan de hoy',
  'Your history, completed workouts and saved routines will not be deleted.': 'Tu historial, tus entrenamientos completados y tus rutinas guardadas no se borrarán.',
  'Work up to the top set and stop while technique is still good. A variation (deficit, block pull) can replace it.': 'Sube hasta la serie principal y para mientras la técnica siga siendo buena. Una variante (con déficit, desde bloques) puede sustituirlo.',
  'Move the bar as fast as you can; every rep crisp.': 'Mueve la barra lo más rápido que puedas; cada repetición limpia.',
  'Work up to the top set; a close-grip or board variation can replace the lift.': 'Sube hasta la serie principal; una variante de agarre cerrado o con tabla puede sustituir el ejercicio.',
  'Sit back and drive up fast; stop a set when speed drops.': 'Siéntate hacia atrás y sube rápido; termina la serie cuando baje la velocidad.',
  'Light load with the cuff: 30-15-15-15 reps, 30 seconds rest. Moderate pressure only; take the cuff off at the end of the exercise and stop if you feel numbness, tingling or pain.': 'Carga ligera con el manguito: 30-15-15-15 repeticiones, 30 segundos de descanso. Solo presión moderada; quita el manguito al terminar el ejercicio y para si notas entumecimiento, hormigueo o dolor.',
  'Conversation pace (zone 1–2). If you cannot talk, slow down.': 'Ritmo de conversación (zona 1–2). Si no puedes hablar, baja el ritmo.',
  'Warm-up, easy.': 'Calentamiento, fácil.',
  'Intervals of 4 minutes hard (about 9 out of 10), 3–4 minutes easy between. Build from 3 to 5 intervals across the block.': 'Intervalos de 4 minutos duros (alrededor de 9 sobre 10), con 3–4 minutos fáciles entre ellos. Sube de 3 a 5 intervalos a lo largo del bloque.',
  'Cool-down, easy.': 'Vuelta a la calma, fácil.',
  'Conversation pace.': 'Ritmo de conversación.',
  'The longest session of the week, truly easy.': 'La sesión más larga de la semana, realmente fácil.',
  'Truly easy: you can hold a conversation.': 'Realmente fácil: puedes mantener una conversación.',
  'Repeats of 6–10 minutes at threshold effort, one minute easy between. Start with 2–3 repeats and add time week by week.': 'Repeticiones de 6–10 minutos a esfuerzo de umbral, con un minuto fácil entre ellas. Empieza con 2–3 repeticiones y añade tiempo semana a semana.',
  'Easy spin or ride.': 'Pedaleo o salida fácil.',
  'One continuous block at threshold effort.': 'Un bloque continuo a esfuerzo de umbral.',
  'Easy, conversation pace.': 'Fácil, ritmo de conversación.',
  'Easy, with 4–6 relaxed strides of about 20 seconds near the end.': 'Fácil, con 4–6 progresiones relajadas de unos 20 segundos hacia el final.',
  'The longest session of the week, easy.': 'La sesión más larga de la semana, fácil.',
  '4 × 4 minutes hard (about 8–9 out of 10), 3 minutes easy between.': '4 × 4 minutos duros (alrededor de 8–9 sobre 10), con 3 minutos fáciles entre ellos.',
  'Kettlebell swings in sets of 10–15 with short rests; stop before your form fades.': 'Balanceos de kettlebell en series de 10–15 con descansos cortos; para antes de que se deteriore la técnica.',
  'Steady aerobic work, conversation pace.': 'Trabajo aeróbico constante, ritmo de conversación.',
  'Smooth, moderate effort.': 'Esfuerzo moderado y fluido.',
  'Burpees in short sets; scale to step-backs if needed.': 'Burpees en series cortas; escala a pasos atrás si hace falta.',
  'Warm-up: jump rope or light skipping.': 'Calentamiento: comba o saltitos ligeros.',
  'Rounds of dumbbell or barbell thrusters, farmers walks and bear crawls with short rests. Keep the loads light enough to repeat.': 'Rondas de thrusters con mancuernas o barra, paseos del granjero y bear crawls con descansos cortos. Mantén cargas lo bastante ligeras para repetir.',
  'Battle ropes, intervals of 20 seconds on, 40 off.': 'Cuerdas de batalla, intervalos de 20 segundos de trabajo y 40 de descanso.',
  'Heavy carry, about 40 meters or 40 seconds.': 'Acarreo pesado, unos 40 metros o 40 segundos.',
  '20–30 seconds of bear crawl.': '20–30 segundos de bear crawl.',
  'Repeats of 3–5 minutes at a hard but sustainable pace, 2 minutes easy between.': 'Repeticiones de 3–5 minutos a un ritmo duro pero sostenible, con 2 minutos fáciles entre ellas.',
  'Moderate to hard, steady rhythm.': 'De moderado a duro, ritmo constante.',
  'Burpees in short sets, switch to step-backs if form fades.': 'Burpees en series cortas; cambia a pasos atrás si se deteriora la técnica.',
  'Kettlebell swings in sets of 15–20.': 'Balanceos de kettlebell en series de 15–20.',
  'Run at a steady pace.': 'Corre a un ritmo constante.',
  'Immediately after the run, keep a steady effort.': 'Justo después de correr, mantén un esfuerzo constante.',
  'Run again on tired legs.': 'Vuelve a correr con las piernas cansadas.',
  'Repeats of 4–6 minutes at a hard but sustainable pace, 2 minutes easy between.': 'Repeticiones de 4–6 minutos a un ritmo duro pero sostenible, con 2 minutos fáciles entre ellas.',
  'Burpees in short sets.': 'Burpees en series cortas.',
  '30 seconds of bear crawl.': '30 segundos de bear crawl.',
  'Battle ropes, 20 seconds on, 40 off.': 'Cuerdas de batalla, 20 segundos de trabajo y 40 de descanso.',
  'Immediately after the run.': 'Justo después de correr.',
  'Finish with kettlebell swings.': 'Termina con balanceos de kettlebell.',
  'Easy: you can speak in full sentences.': 'Fácil: puedes hablar en frases completas.',
  'Easy, conversation pace; brisk walking is fine.': 'Fácil, ritmo de conversación; caminar a buen paso está bien.',
  'Smooth, easy rhythm.': 'Ritmo suave y fácil.',
  'Finisher: steady, hard-but-sustainable effort.': 'Final: esfuerzo constante, duro pero sostenible.',
