  'Enter the marks you got in your control week. Leave a test empty if you did not do it: it keeps the previous mark and is not scored.': 'Escribe las marcas que hiciste en tu semana de control. Deja vacía una prueba si no la hiciste: conserva la marca anterior y no se puntúa.',
