  'Version {0} → {1} · source {2}': 'Versión {0} → {1} · fuente {2}',
  'If you update, your marks are kept, the levels and targets are recalculated and the next block uses the new tests. Your previous version stays in your history.': 'Si actualizas, se conservan tus marcas, se recalculan los niveles y los objetivos y el siguiente bloque usa las nuevas pruebas. Tu versión anterior queda en tu historial.',
  'Update my plan': 'Actualizar mi plan',
