  'Current': 'Actual',
  'Delete this profile?': '¿Borrar este perfil?',
  'Only profiles that were never published or used can be deleted. Otherwise archive it.': 'Solo se pueden borrar perfiles que nunca se publicaron ni se usaron. Si no, archívalo.',
  'Only administrators manage the profiles': 'Solo los administradores gestionan los perfiles',
  'Oposiciones': 'Oposiciones',
  'Official profiles: tests, minimum marks and the source of each convocatoria. A changed convocatoria is a new version; running plans keep theirs.': 'Perfiles oficiales: pruebas, marcas mínimas y fuente de cada convocatoria. Una convocatoria que cambia es una versión nueva; los planes en marcha conservan la suya.',
  'Members only see a profile once it is published, and only if the Oposiciones program is published in the Premium catalogue.': 'Los socios solo ven un perfil cuando está publicado, y solo si el programa Oposiciones está publicado en el catálogo Premium.',
