  'Order and choose what to see in Home and Progress': 'Ordena y elige qué ver en Inicio y Progreso',
  'A full physical-preparation plan — strength, power, speed, endurance and more — built to pass the physical tests of your exam. The official tests and marks only set your starting point, your targets and your checkpoints.': 'Un plan completo de preparación física —fuerza, potencia, velocidad, resistencia y más— para superar las pruebas físicas de tu oposición. Las pruebas y marcas oficiales solo fijan tu punto de partida, tus objetivos y tus controles.',
